<template><section v-if="visible" class="order-return-panel" aria-labelledby="order-return-title"><h2 id="order-return-title">Trả hàng &amp; hoàn về</h2><p v-if="error" role="alert">{{ error }}</p><p v-if="success" role="status">{{ success }}</p><button class="button button-outline" :disabled="busy" @click="load">Cập nhật yêu cầu trả</button>
<template v-if="data"><p v-if="data.request"><strong>{{ labels[data.request.status] || data.request.status }}</strong> · {{ data.request.kind==='CARRIER_RETURN'?'Hoàn từ hãng vận chuyển':'Yêu cầu trả toàn bộ đơn' }}</p><p v-if="data.request">{{ data.request.reason }}</p><p v-if="data.request?.carrierRequestStatus==='UNKNOWN' || data.request?.carrierRequestStatus==='SENDING'">Phản hồi yêu cầu hoàn chưa rõ. Cần đối chiếu tracking GHN; không gửi lặp yêu cầu.</p><p v-if="data.request?.status==='INSPECTED'">{{ data.request.inspection }}<br/>{{ data.request.restock?'Đã nhập lại tồn sau kiểm tra.':'Hàng không được nhập lại tồn.' }}</p>
<form v-if="buyer && !data.request && ['DELIVERED','COMPLETED'].includes(status)" :aria-busy="busy" @submit.prevent="act('',{reason})"><label for="return-reason">Lý do trả toàn bộ đơn</label><textarea id="return-reason" v-model.trim="reason" required minlength="10" maxlength="1000" rows="3" :disabled="busy"/><button class="button button-outline" type="submit" :disabled="busy">Gửi yêu cầu trả hàng</button></form>
<button v-if="seller && data.request?.kind==='BUYER_RETURN' && data.request.status==='REQUESTED'" class="button button-outline" :disabled="busy" @click="act('/approve',{})">Duyệt yêu cầu trả</button>
<button v-if="seller && !data.request && ['DELIVERY_FAILED','RETURN_REQUESTED'].includes(data.shipmentState)" class="button button-outline" :disabled="busy" @click="act('/carrier',{})">Yêu cầu GHN thử nghiệm hoàn về</button>
<form v-if="seller && (data.request?.status==='APPROVED' || !data.request && data.shipmentState==='RETURNED')" :aria-busy="busy" @submit.prevent="act('/inspection',{received,condition,restock})"><h3>Nhận &amp; kiểm tra toàn bộ hàng trả</h3><label class="return-check"><input v-model="received" type="checkbox" :disabled="busy"/>Tôi đã thực nhận toàn bộ hàng và kiểm tra trực tiếp.</label><label for="return-condition">Tình trạng sau kiểm tra</label><textarea id="return-condition" v-model.trim="condition" required minlength="10" maxlength="1000" rows="3" :disabled="busy"/><label class="return-check"><input v-model="restock" type="checkbox" :disabled="busy"/>Toàn bộ hàng còn đủ điều kiện bán; nhập lại tồn đã trừ của đơn.</label><button class="button button-primary" type="submit" :disabled="busy || !received">Ghi nhận kết quả kiểm tra</button></form>
<p>Yêu cầu trả, hoàn hàng của hãng và hoàn tiền là các bước riêng. Chưa tích hợp vận đơn lấy hàng trả từ người mua hoặc dịch vụ hoàn tiền. Gian hàng và người mua cần thống nhất cách bàn giao; không có xác nhận hoàn tiền tự động.</p></template></section></template>
<script setup>
import {computed,onBeforeUnmount,ref,watch} from 'vue';import {marketplaceRequest as request} from '../../services/marketplace.js';
const props=defineProps({endpoint:String,orderId:Number,status:String,buyer:Boolean});const data=ref(null),busy=ref(false),error=ref(''),success=ref(''),reason=ref(''),condition=ref(''),received=ref(false),restock=ref(false);let sequence=0;
const seller=computed(()=>props.endpoint==='/seller/orders'),labels={REQUESTED:'Chờ gian hàng duyệt',APPROVED:'Đã duyệt · chờ nhận và kiểm tra',INSPECTED:'Đã kiểm tra hàng trả'},visible=computed(()=>data.value?.request||['SHIPPING','DELIVERED','COMPLETED'].includes(props.status)||['DELIVERY_FAILED','RETURN_REQUESTED','RETURNING','RETURNED'].includes(data.value?.shipmentState));
const path=()=>props.endpoint+'/'+props.orderId+'/return';async function load(){const ticket=++sequence;error.value='';try{const result=await request(path());if(ticket===sequence)data.value=result;}catch(e){if(ticket===sequence)error.value=e.message;}}
async function act(suffix,body){if(busy.value)return;busy.value=true;error.value='';success.value='';const ticket=sequence;try{const result=await request(path()+suffix,'POST',body,false);if(ticket===sequence){data.value=result;success.value='Đã ghi nhận trên máy chủ. Chưa có xác nhận hoàn tiền.';}}catch(e){if(ticket===sequence)error.value=e.message;}finally{busy.value=false;}}watch(()=>[props.orderId,props.endpoint,props.status],load,{immediate:true});onBeforeUnmount(()=>sequence++);
</script>
<style scoped>.order-return-panel{padding:28px 0 72px;border-top:1px solid var(--bm-border);overflow-wrap:anywhere}.order-return-panel h2{font-size:var(--bm-type-section)}.order-return-panel p{max-width:75ch;line-height:1.65}.order-return-panel form{max-width:720px;margin-block:24px}.order-return-panel label{display:block;margin:16px 0 8px}.order-return-panel textarea{width:100%;min-height:96px;font:inherit;box-sizing:border-box;padding:12px;border:1px solid var(--bm-control-border);border-radius:var(--bm-radius-control);background:var(--bm-surface);resize:vertical}.order-return-panel button{margin:12px 12px 12px 0;max-width:100%}.return-check{display:flex!important;gap:12px;line-height:1.65}.return-check input{width:20px;height:20px;flex-shrink:0;accent-color:var(--bm-forest)}.order-return-panel :focus-visible{outline:3px solid var(--bm-forest);outline-offset:3px}</style>
